"use strict";
// Reference-exclusion corpus: Word documents generated by
// test-fixtures/reference-corpus/generate-corpus.py, converted with the
// production LibreOffice -> PDF.js path, stored as compact real geometry.
//
// Covers APA, Harvard, Chicago (author-date and notes-bibliography), IEEE,
// Vancouver, MLA, OSCOLA, URL-only and mixed lists; 20+ heading wordings
// with numbering, chapter prefixes, trailing punctuation, small caps and
// letter spacing; hanging / no indent, double spacing, mixed fonts, stray
// quotes, tables, auto-numbering, 2-entry and 29-entry lists; appendices,
// declarations, Task 2 sections, second lists, word counts, running headers
// and footers, tables of contents and cover pages; plus negative documents
// that must NOT be excluded or must fail closed to administrator review;
// annotated bibliographies (citations excluded, every annotation kept); and
// unheaded prose after a list that starts with "Patients", "Prevention",
// "Nonetheless", "Issues" or "Volunteers" (must stay in the input).
// Full-given-name author lists ("Al Halbusi, Hussam, ..., & Al-Busaidi,
// Adil S." with the year on the next line), sentence-like article titles,
// wrapped page/DOI lines, Harvard/MLA full names, numbered APA, blank lines
// between entries, two-page running heads, and prose after a list that cites
// "(Barney, 1991, pp. 99-120)" (generate-fullname*.py); Chicago/MLA web-source
// bibliographies with n.d., quoted titles first and wrapped URLs
// (generate-chicago-web.py); PowerPoint decks and Word lists with bulleted
// entries over several "References" slides (generate-slides-bullets.py).
// Offline: no provider, Telegram or Render calls.
const assert = require("node:assert/strict");
const path = require("node:path");
const { inspectReferenceSections } = require("./jk-reference-sections.js");
const scan = require("./jk-scan-text.js");

const dir = path.join(__dirname, "test-fixtures", "reference-corpus");
const specs = require(path.join(dir, "specs.json"));
const norm = s => String(s).replace(/\s+/g, " ").replace(/[‘’]/g, "'").replace(/[“”]/g, '"');
const failures = [];

for (const spec of specs) {
  const doc = require(path.join(dir, spec.name + ".json"));
  const text = doc.text;
  const problems = [];
  const inspection = inspectReferenceSections(text, scan.findBibliographyStart(text), [], doc);
  if (spec.expectReview) {
    if (!inspection.reviews.length) problems.push("expected administrator review, got none");
    // Never offer a reference entry as the point to resume scanning.
    for (const candidate of inspection.reviews.flatMap(review => review.candidates || [])) {
      const at = norm(text.slice(candidate.offset, candidate.offset + 40));
      if ((spec.entries || []).some(entry => at.startsWith(norm(entry).slice(0, 20)))) problems.push("reference offered as inclusion point: " + at);
    }
  } else {
    if (inspection.reviews.length) problems.push("unexpected review: " + inspection.reviews[0].reason);
    if (spec.noRefs && inspection.ranges.length) problems.push("false reference range");
    if (!inspection.reviews.length) {
      const ai = norm(scan.buildAiInput(text, doc, []).text);
      const sim = norm(scan.buildSimilarityInput(text, scan.FILTER_MODE_FILTERED, [], doc).text);
      for (const [label, input] of [["AI", ai], ["Similarity", sim]]) {
        const leaked = spec.entries.filter(e => input.includes(norm(e)));
        if (leaked.length) problems.push(label + " input contains " + leaked.length + " reference entries, e.g. " + JSON.stringify(leaked[0]));
        if (spec.secondList && input.includes(norm("Brophy, R.H. and Fillingham"))) problems.push(label + " input contains the second reference list");
        if (spec.keepBefore && !input.includes(norm(spec.keepBefore))) problems.push(label + " input lost body prose");
        // Annotated bibliographies: every annotation is the student's prose.
        const lostAnnotations = (spec.keepAll || []).filter(k => !input.includes(norm(k)));
        if (lostAnnotations.length) problems.push(label + " input lost " + lostAnnotations.length + " annotation(s), e.g. " + JSON.stringify(lostAnnotations[0]));
        if (spec.keepAfter && !input.includes(norm(spec.keepAfter))) problems.push(label + " input lost text that follows the references");
      }
    }
  }
  if (problems.length) failures.push(spec.name + ": " + problems.join("; "));
}

// Regression: MLA-style annotated bibliography with an institutional author
// and a lowercase surname. Annotations are substantial student-authored prose;
// excluding them to the end must not leave an effectively empty provider input.
const annotationA = "The professional guidance offers important context for adolescent well-being and explains why social media cannot be treated as entirely harmful or entirely beneficial. It supports a careful analysis of online experiences, developmental factors, bullying, and healthy habits.";
const annotationB = "This longitudinal research describes how young people may experience digital platforms differently depending on their circumstances. It gives useful evidence for comparing general population trends with individual differences, and it warns against broad causal conclusions.";
const mlaAnnotated = [
  "Annotated Bibliography",
  "",
  'American Psychological Association. "Health Advisory on Social Media Use in Adolescence." American Psychological Association, May 2023, https://www.apa.org/topics/social-media-internet/health-advisory-adolescent-social-media-use.',
  "",
  annotationA,
  "",
  'boyd, danah. It\'s Complicated: The Social Lives of Networked Teens. Yale UP, 2014, https://doi.org/10.12987/9780300166439.',
  "",
  annotationB,
  ""
].join("\n");
try {
  const checked = scan.buildSimilarityInput(mlaAnnotated, scan.FILTER_MODE_FILTERED);
  const ai = scan.buildAiInput(mlaAnnotated);
  for (const prepared of [checked, ai]) {
    assert(prepared.text.includes(annotationA), "corporate-author annotation must remain");
    assert(prepared.text.includes(annotationB), "lowercase-author annotation must remain");
    assert(!prepared.text.includes("Health Advisory on Social Media"), "corporate MLA entry must be excluded");
    assert(!prepared.text.includes("The Social Lives of Networked Teens"), "lowercase MLA entry must be excluded");
    assert(prepared.text.split(/\\s+/u).length >= 60, "annotated prose must remain substantial");
  }
} catch (error) {
  failures.push("mla_corporate_lowercase_annotated: " + error.message);
}

assert.deepEqual(failures, [], "reference corpus failures:\n" + failures.join("\n"));
console.log("PASS: reference corpus — " + specs.length + " real-geometry documents: every bibliography excluded, annotations and following prose kept, mixed content fails closed");
